PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT ?empresa (SUM(?g) AS ?gas_miles_m3)
WHERE {
  ?p a energia:WellProduction ;
     energia:declaredBy ?c ;
     energia:gas ?g .
  ?c energia:name ?empresa .
}
GROUP BY ?empresa
ORDER BY DESC(?gas_miles_m3)
LIMIT 1

PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT ?empresa (SUM(?gas_concesion * ?pct / 100) AS ?gas_que_le_corresponde_miles_m3)
WHERE {
  ?c energia:name ?empresa .
  FILTER(?empresa = "TOTAL AUSTRAL S.A.")
  ?s a energia:Stake ;
     energia:partner ?c ;
     energia:percent ?pct ;
     energia:inConcession ?con .
  {
    SELECT ?con (SUM(?g) AS ?gas_concesion)
    WHERE {
      ?p a energia:WellProduction ;
         energia:inConcession ?con ;
         energia:gas ?g .
    }
    GROUP BY ?con
  }
}
GROUP BY ?empresa
LIMIT 50

PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT ?concesion ?empresa ?porcentaje ?petroleoConcesion ((?petroleoConcesion * ?porcentaje / 100) AS ?petroleoQueLeCorresponde)
WHERE {
  ?stake a energia:Stake ;
         energia:partner ?socia ;
         energia:percent ?porcentaje ;
         energia:inConcession ?c .
  ?socia energia:name ?empresa .
  FILTER(REGEX(?empresa, "^YPF", "i"))
  ?c energia:name ?concesion .
  {
    SELECT ?c (SUM(?oil) AS ?petroleoConcesion)
    WHERE {
      ?p a energia:WellProduction ;
         energia:inConcession ?c ;
         energia:oil ?oil .
    }
    GROUP BY ?c
  }
}
ORDER BY DESC(?petroleoQueLeCorresponde)
LIMIT 50

