PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT ?operadora (COUNT(DISTINCT ?pozo) AS ?pozos)
WHERE {
  ?pozo a energia:Well ;
        energia:operator ?empresa .
  ?empresa energia:name ?operadora .
  FILTER(REGEX(?operadora, "^YPF", "i"))
}
GROUP BY ?operadora
LIMIT 50

