SELECT (COUNT(DISTINCT ?concesion) AS ?concesiones_para_revisar)
WHERE {
  ?concesion a energia:ConcessionToReview .
}
LIMIT 50

PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT ?empresa (SUM(?petroleo) AS ?petroleo_m3)
WHERE {
  ?prod a energia:WellProduction ;
        energia:declaredBy ?e ;
        energia:oil ?petroleo .
  ?e energia:name ?empresa .
  FILTER(STRSTARTS(UCASE(STR(?empresa)), "YPF"))
}
GROUP BY ?empresa
ORDER BY DESC(?petroleo_m3)
LIMIT 50
